insert into public.english_production_paths (slug, competency_slug, skill, title, goal) values
    ('article-reference-writing', 'article-reference', 'writing', 'Articles in everyday messages',
     'Introduce things your reader has never heard about, and refer back to things they can already identify.');

with briefs(family, stage, form, title, brief) as (values
    ('club-lost-property', 1, 1, 'A note for the sports club',
        'Write three short sentences for the club secretary. Use each word shown exactly once in its sentence.'),
    ('craft-room-handover', 1, 2, 'Hand over the craft room',
        'Leave a note for the next volunteer. Use each word shown exactly once in its sentence.'),
    ('station-help-desk', 2, 1, 'Updates from the station help desk',
        'A coworker is taking over the desk. Write three updates in your own words. Use each word shown exactly once in its sentence.'),
    ('community-picnic', 2, 2, 'Messages for a community picnic',
        'Write three short updates for the organiser. Use each word shown exactly once in its sentence.'),
    ('building-repair-desk', 3, 1, 'Messages to the building caretaker',
        'Write three practical sentences to help the caretaker with today’s jobs. Use each word shown exactly once in its sentence.'),
    ('school-play-handover', 3, 2, 'Notes before a school play',
        'You are handing over to the person looking after props. Write one sentence for each situation. Use each word shown exactly once in its sentence.'),
    ('holiday-flat-arrival', 4, 1, 'Help a guest arrive',
        'Write three separate lines for the guest arriving at the holiday flat. Use each word shown exactly once in its sentence.'),
    ('garden-sale-setup', 4, 2, 'Set up the plant sale',
        'Write one sentence per note for your neighbourhood plant sale. Use each word shown exactly once in its sentence.')
), slots(family, position, prompt, noun, article, anchors, bare_after, model, explanation) as (values
    ('club-lost-property', 1, 'You found a forgotten item in the changing room. The secretary has heard nothing about it. Tell them what you found and where. Use bottle.',
        'bottle', 'a', 'found|saw|noticed|picked', 'found|saw|noticed', 'I found a bottle under the bench.', 'Introduce the item with a because the reader cannot identify it yet. Bottle starts with a consonant sound.'),
    ('club-lost-property', 2, 'The secretary has asked about one particular item: the club’s spare key. Tell them where you put that item. Use key.',
        'key', 'the', 'put|left|placed|is|stored|kept', 'put|left|placed|stored|kept', 'I left the key in your drawer.', 'The reader already knows which key you mean, so use the.'),
    ('club-lost-property', 3, 'The outdoor event starts in ten minutes and it is raining. Ask the secretary to bring any suitable item to keep you dry. Use umbrella.',
        'umbrella', 'an', 'bring|lend|get|need|fetch|take', 'bring|lend|get|need|fetch|take', 'Could you bring an umbrella to the gate?', 'Introduce an unspecified item with an because umbrella begins with a vowel sound.'),
    ('craft-room-handover', 1, 'A volunteer asks about the room’s one large work surface. Tell them where that particular item is. Use table.',
        'table', 'the', 'is|stands|moved|put|find|left', 'moved|put|find|left', 'You will find the table beside the window.', 'The reader can identify the particular table you are talking about.'),
    ('craft-room-handover', 2, 'One drawing needs to go home in a container. Ask the volunteer to bring any suitable one. Use envelope.',
        'envelope', 'an', 'bring|need|find|take|get|use', 'bring|need|find|take|get|use', 'Please bring an envelope for the drawing.', 'Envelope starts with a vowel sound, so use an for a new, unspecified one.'),
    ('craft-room-handover', 3, 'You bought one new tool this morning. The volunteer knows nothing about it. Tell them what you bought and when. Use brush.',
        'brush', 'a', 'bought|got|picked|purchased', 'bought|got|purchased', 'I bought a brush this morning.', 'Brush starts with a consonant sound. Use a to introduce one brush.'),
    ('station-help-desk', 1, 'A passenger found something near platform two. Your coworker has not heard about it. Say what the passenger found and where. Use wallet.',
        'wallet', 'a', 'found|saw|noticed|picked|handed|brought', 'found|saw|noticed|brought', 'A passenger found a wallet near platform two.', 'Use a with wallet when your coworker has no particular wallet in mind.'),
    ('station-help-desk', 2, 'Your coworker asked earlier about the one parcel addressed to the duty manager. Tell them where you left it. Use parcel.',
        'parcel', 'the', 'put|left|placed|is|kept|stored', 'put|left|placed|kept|stored', 'I left the parcel in the manager’s office.', 'Both readers know which parcel is meant, so use the.'),
    ('station-help-desk', 3, 'The public phone is in use. Ask your coworker to help a visitor reserve one car, with no particular driver in mind. Use airport taxi as two words.',
        'airport taxi', 'an', 'book|call|find|order|get|arrange', 'book|call|find|order|get|arrange', 'Could you book an airport taxi for this visitor?', 'The article goes before airport taxi. The first sound in airport is a vowel sound.'),
    ('community-picnic', 1, 'The organiser has asked about the one basket reserved for the children’s lunch. Tell them where you put it. Use basket.',
        'basket', 'the', 'put|left|placed|is|stored', 'put|left|placed|stored', 'I left the basket under your chair.', 'The organiser can identify that basket.'),
    ('community-picnic', 2, 'You stopped at a shop to buy something for a child who cannot eat the cake. Nobody knows what you bought. Say what it was. Use orange.',
        'orange', 'an', 'bought|got|picked|purchased', 'bought|got|purchased', 'I bought an orange for Maya.', 'Use an before orange to introduce an item your reader does not know about.'),
    ('community-picnic', 3, 'There is nowhere to put the drinks. Ask a volunteer to bring any small piece of furniture people can sit on. Use stool.',
        'stool', 'a', 'bring|get|find|fetch|need|borrow', 'bring|find|get|fetch|need|borrow', 'Please bring a stool for the juice bottles.', 'Use a because any suitable stool will do.'),
    ('building-repair-desk', 1, 'You noticed a new problem in the upstairs corridor. The caretaker has not heard about it. Describe what you noticed and where. Use leak.',
        'leak', 'a', 'noticed|found|saw|spotted', 'noticed|found|saw|spotted', 'I noticed a leak in the upstairs corridor.', 'Use a to introduce the problem, and leak starts with a consonant sound.'),
    ('building-repair-desk', 2, 'The caretaker has already asked about the glass screen next to the entrance. Say when that particular item will be ready again. Use screen.',
        'screen', 'the', 'will|ready|fixed|repair|finish', 'repair|finish|fixed', 'The screen will be ready at three.', 'The screen is already known to both people.'),
    ('building-repair-desk', 3, 'Nobody on duty knows how to fix the electrics. Ask the caretaker to contact any suitable professional. Use electrician.',
        'electrician', 'an', 'call|contact|find|get|ask|need', 'call|contact|find|get|ask|need', 'Please call an electrician this morning.', 'Electrician starts with a vowel sound. Use an when you could mean any suitable person.'),
    ('school-play-handover', 1, 'The volunteer has asked where you left the one hat the lead actor wears. Tell them where it is. Use hat.',
        'hat', 'the', 'where|left|is|put|find|placed|shelf', 'left|put|find|placed', 'I left the hat on the shelf.', 'The volunteer knows which hat you mean.'),
    ('school-play-handover', 2, 'One card is needed to show which way visitors should walk. Ask for any object that points in the right direction. Use arrow.',
        'arrow', 'an', 'draw|add|put|print|need|use', 'draw|add|put|print|need|use', 'Please draw an arrow on the card.', 'An introduces an unspecified object. Arrow starts with a vowel sound.'),
    ('school-play-handover', 3, 'A parent has given you an extra item for the audience area. The other volunteer has not heard about it. Tell them what you received. Use cushion.',
        'cushion', 'a', 'gave|got|brought|received|donated', 'gave|got|brought|received|donated', 'A parent brought a cushion for the audience area.', 'Use a for an item that is being introduced.'),
    ('holiday-flat-arrival', 1, 'The guest asked about the flat’s own door bell. Tell them where it is. Use bell.',
        'bell', 'the', 'is|find|see|stands|hangs|hang|beside', 'find|see', 'The bell is beside the front door.', 'Both people can identify the particular bell.'),
    ('holiday-flat-arrival', 2, 'After check-in, you can provide any extra layer to keep the guest warm. Offer to leave one in the bedroom. Use blanket.',
        'blanket', 'a', 'leave|bring|put|get|provide', 'leave|bring|put|get|provide', 'I can leave a blanket on the bed.', 'Blanket starts with a consonant sound, and the guest has not been told about a particular one.'),
    ('holiday-flat-arrival', 3, 'You can give the guest any device that lets their plug fit the wall socket. Offer one. Use adapter.',
        'adapter', 'an', 'offer|lend|give|bring|provide|get', 'offer|lend|give|bring|provide|get', 'I can lend you an adapter for your charger.', 'Use an for any suitable adapter because its first sound is a vowel.'),
    ('garden-sale-setup', 1, 'You bought an extra display item that can hold a pot. The team has not seen it. Tell them what you bought. Use stand.',
        'stand', 'a', 'bought|got|found|picked|purchased', 'bought|got|found|purchased', 'I bought a stand for the largest pot.', 'Use a because you are introducing a new stand to the reader.'),
    ('garden-sale-setup', 2, 'The team asked about the one sign that shows when the sale starts. Say where you put it. Use sign.',
        'sign', 'the', 'put|left|placed|is|hung|attached', 'put|left|placed|hung|attached', 'I hung the sign on the front gate.', 'The sign is the specific one the team already knows about.'),
    ('garden-sale-setup', 3, 'The card reader is too far from the wall. Ask for any device that will make the cable longer. Use extension lead as two words.',
        'extension lead', 'an', 'bring|find|fetch|need|borrow|get', 'bring|find|fetch|need|borrow|get', 'Could you bring an extension lead for the card reader?', 'Extension begins with a vowel sound. Use an for any suitable extension lead.')
)
insert into public.english_production_tasks (family, path_slug, stage, form, title, brief, rubric_version, slots)
select briefs.family, 'article-reference-writing', stage, form, title, brief, 'article-choice-v1',
    jsonb_agg(jsonb_build_object('prompt', prompt, 'noun', noun, 'article', article,
        'anchors', string_to_array(anchors, '|'), 'bare_after', string_to_array(bare_after, '|'),
        'model', model, 'explanation', explanation) order by position)
from briefs join slots on briefs.family = slots.family
group by briefs.family, stage, form, title, brief;
